bool LoadInputs(std::string& error) {
    ::demo::detail::DemoInputsLoaded = true;
    ::demo::detail::DemoInputs::Config::port_ = {};
    ::demo::detail::DemoInputs::Config::debug_ = {};
    ::demo::detail::DemoInputs::Config::name_ = {};
    ::demo::detail::DemoInputs::Config::tag_ = {};
    ::demo::detail::DemoInputs::Config::timeout_ = {};
    ::demo::detail::DemoInputs::Config::rate_ = {};
    ::demo::detail::DemoInputs::Config::color_ = {};
    ::demo::detail::DemoInputs::Config::level_ = {};
    ::demo::detail::DemoInputs::Config::note_ = {};
    ::demo::detail::DemoInputs::Config::ratio_ = {};
    ::demo::detail::DemoInputs::Config::count_ = {};
    ::demo::detail::DemoInputs::Config::wait_ = {};
    std::string problems;
    std::string raw;
    if (EnvText("CANON_TEST_PORT", raw)) {
        int64_t val{};
        if (!ParseIntLiteral(raw, val)) {
            problems += "CANON_TEST_PORT: not a valid Int\n";
        } else if (val < -2147483648 || val > 2147483647) {
            problems += "CANON_TEST_PORT: outside its refinement range\n";
        } else if (val < 1 || val > 65535) {
            problems += "CANON_TEST_PORT: outside its refinement range\n";
        } else {
            ::demo::detail::DemoInputs::Config::port_ = static_cast<int32_t>(val);
        }
    } else {
        problems += "CANON_TEST_PORT: not set\n";
    }
    if (EnvText("CANON_TEST_DEBUG", raw)) {
        bool val{};
        if (!ParseBoolLiteral(raw, val)) {
            problems += "CANON_TEST_DEBUG: not a valid Bool\n";
        } else {
            ::demo::detail::DemoInputs::Config::debug_ = val;
        }
    } else {
        problems += "CANON_TEST_DEBUG: not set\n";
    }
    if (EnvText("CANON_TEST_NAME", raw)) {
        std::string val{};
        if (!ParseStringLiteral(raw, val)) {
            problems += "CANON_TEST_NAME: not a valid String\n";
        } else if (static_cast<int64_t>(val.size()) < 1 || static_cast<int64_t>(val.size()) > 10) {
            problems += "CANON_TEST_NAME: outside its refinement range\n";
        } else {
            ::demo::detail::DemoInputs::Config::name_ = std::move(val);
        }
    }
    if (EnvText("CANON_TEST_TAG", raw)) {
        static constexpr uint32_t kPattern[] = {
            6,
            2, 1, 1, 0,
            3, 2, 25, 1,
            3, 3, 25, 1,
            3, 4, 25, 1,
            2, 5, 2, 0,
            0, 0, 0, 0,
            65, 90,
        };
        std::string val{};
        if (!ParseStringLiteral(raw, val)) {
            problems += "CANON_TEST_TAG: not a valid String\n";
        } else if (!MatchPattern(kPattern, val)) {
            problems += "CANON_TEST_TAG: does not match its pattern\n";
        } else {
            ::demo::detail::DemoInputs::Config::tag_ = std::move(val);
        }
    }
    if (EnvText("CANON_TEST_TIMEOUT", raw)) {
        int64_t val{};
        if (!ParseDurationLiteral(raw, val)) {
            problems += "CANON_TEST_TIMEOUT: not a valid Duration\n";
        } else if (val < 1000 || val > 60000) {
            problems += "CANON_TEST_TIMEOUT: outside its refinement range\n";
        } else {
            ::demo::detail::DemoInputs::Config::timeout_ = std::chrono::milliseconds(val);
        }
    }
    if (EnvText("CANON_TEST_RATE", raw)) {
        double val{};
        if (!ParseFloatLiteral(raw, val)) {
            problems += "CANON_TEST_RATE: not a valid Float\n";
        } else if (std::fabs(val) >= 3.4028235677973366e+38) {
            problems += "CANON_TEST_RATE: outside its refinement range\n";
        } else if (static_cast<float>(val) < 0.0 || static_cast<float>(val) > 1.0) {
            problems += "CANON_TEST_RATE: outside its refinement range\n";
        } else {
            ::demo::detail::DemoInputs::Config::rate_ = static_cast<float>(val);
        }
    }
    if (EnvText("CANON_TEST_COLOR", raw)) {
        const auto val = ::demo::ColorFromWire(raw);
        if (!val || *val == ::demo::Color::blue) {
            problems += "CANON_TEST_COLOR: not a member of Color\n";
        } else {
            ::demo::detail::DemoInputs::Config::color_ = (*val);
        }
    }
    if (EnvText("CANON_TEST_LEVEL", raw)) {
        const auto val = ::demo::TierFromWire(raw);
        if (!val) {
            problems += "CANON_TEST_LEVEL: not a member of Level\n";
        } else {
            ::demo::detail::DemoInputs::Config::level_ = (*val);
        }
    }
    if (EnvText("CANON_TEST_NOTE", raw)) {
        std::string val{};
        if (!ParseStringLiteral(raw, val)) {
            problems += "CANON_TEST_NOTE: not a valid String\n";
        } else {
            ::demo::detail::DemoInputs::Config::note_ = std::move(val);
        }
    }
    if (EnvText("CANON_TEST_RATIO", raw)) {
        double val{};
        if (!ParseFloatLiteral(raw, val)) {
            problems += "CANON_TEST_RATIO: not a valid Float\n";
        } else {
            ::demo::detail::DemoInputs::Config::ratio_ = val;
        }
    }
    if (EnvText("CANON_TEST_COUNT", raw)) {
        int64_t val{};
        if (!ParseIntLiteral(raw, val)) {
            problems += "CANON_TEST_COUNT: not a valid Int\n";
        } else {
            ::demo::detail::DemoInputs::Config::count_ = static_cast<int64_t>(val);
        }
    }
    if (EnvText("CANON_TEST_WAIT", raw)) {
        int64_t val{};
        if (!ParseDurationLiteral(raw, val)) {
            problems += "CANON_TEST_WAIT: not a valid Duration\n";
        } else {
            ::demo::detail::DemoInputs::Config::wait_ = std::chrono::milliseconds(val);
        }
    }
    error = problems;
    return problems.empty();
}

